/**
 * EWT Summary — the owner's *SAMPLE TEMPLATE FOR EWT by Rey.xlsx*, live.
 *
 * Two registers, generated by month or by quarter:
 *
 *  - **Supplier EWT · 1601-EQ** — the EWT *we* withheld from suppliers on our
 *    POs (the PO's own "LESS EWT"), which we owe BIR.
 *  - **Client EWT · 1701Q** — the EWT *our clients* withheld from us on their
 *    payments (the order's recorded EWT), which they owe BIR on our behalf.
 *
 * Columns, as the template has them: DATE · REGISTERED NAME · ADDRESS · TIN ·
 * S.I. # · GROSS TAXABLE · NET OF VAT (gross ÷ 1.12 — the template's "INPUT TAX",
 * relabelled at the owner's word) · EWT · STATUS · POP.
 *
 * STATUS is **Paid** once a proof of payment to BIR is attached to the row,
 * **Unpaid** until then (the owner: *"to be considered paid, a proof of payment
 * to BIR should be uploaded"*). The proofs live in `EwtRemittance` (0063).
 *
 * Everything here is pure; `ewt-summary-data.ts` does the reading.
 */
import type { User } from "@prisma/client";
import { isAdmin } from "@/lib/auth";
import { userHasWorkflowRole, type WorkflowRoleAssignments } from "@/lib/workflow-roles";

// --- Who ---------------------------------------------------------------------

/** The owner: *"In admin, payment approver and accounting My Dashboard"*. View, upload and export alike. */
export function canUseEwtSummary(user: User | null | undefined, roles: WorkflowRoleAssignments): boolean {
  if (!user) return false;
  return isAdmin(user) || userHasWorkflowRole(roles, user.id, "payment_approver") || userHasWorkflowRole(roles, user.id, "accounting");
}

// --- When --------------------------------------------------------------------

export type EwtPeriodMode = "month" | "quarter";

export interface EwtPeriod {
  mode: EwtPeriodMode;
  /** "2026-10" for a month, "2026-Q4" for a quarter. */
  key: string;
  /** Inclusive Manila calendar days. */
  from: string;
  to: string;
  /** "October 2026" / "Q4 2026 (October – December)". */
  label: string;
}

const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
const pad = (n: number) => String(n).padStart(2, "0");
const lastDay = (y: number, m: number) => new Date(Date.UTC(y, m, 0)).getUTCDate();

/**
 * The period a request asks for, or the one containing `todayYMD` when it asks
 * for nothing sensible. `key` is "YYYY-MM" or "YYYY-Qn".
 */
export function ewtPeriod(mode: string | undefined, key: string | undefined, todayYMD: string): EwtPeriod {
  const y0 = Number(todayYMD.slice(0, 4));
  const m0 = Number(todayYMD.slice(5, 7));
  if (mode === "quarter") {
    const m = /^(\d{4})-Q([1-4])$/.exec(key ?? "");
    const y = m ? Number(m[1]) : y0;
    const q = m ? Number(m[2]) : Math.ceil(m0 / 3);
    const first = (q - 1) * 3 + 1;
    return {
      mode: "quarter",
      key: `${y}-Q${q}`,
      from: `${y}-${pad(first)}-01`,
      to: `${y}-${pad(first + 2)}-${pad(lastDay(y, first + 2))}`,
      label: `Q${q} ${y} (${MONTHS[first - 1]} – ${MONTHS[first + 1]})`,
    };
  }
  const m = /^(\d{4})-(\d{2})$/.exec(key ?? "");
  const y = m ? Number(m[1]) : y0;
  const mo = m && Number(m[2]) >= 1 && Number(m[2]) <= 12 ? Number(m[2]) : m0;
  return {
    mode: "month",
    key: `${y}-${pad(mo)}`,
    from: `${y}-${pad(mo)}-01`,
    to: `${y}-${pad(mo)}-${pad(lastDay(y, mo))}`,
    label: `${MONTHS[mo - 1]} ${y}`,
  };
}

export const inPeriod = (ymd: string | null, p: { from: string; to: string }): boolean => !!ymd && ymd >= p.from && ymd <= p.to;

// --- The rows ------------------------------------------------------------------

export type EwtKind = "supplier" | "client";

export const EWT_TABLE_TITLE: Record<EwtKind, string> = {
  supplier: "Supplier EWT — 1601-EQ",
  client: "Client EWT — 1701Q",
};

export interface EwtProof {
  path: string;
  name: string;
  uploadedAt: string;
  byName: string;
}

export interface EwtRow {
  kind: EwtKind;
  /** Which row a proof belongs to: a PO's batch id / request id, or the order id. */
  refKey: string;
  /** YYYY-MM-DD. */
  date: string;
  /** How the date was decided, e.g. "PO date", "Payment date". */
  dateBasis: string;
  registeredName: string;
  address: string;
  tin: string;
  siNumber: string;
  /** The PO number or order number the row came from. */
  reference: string;
  href: string | null;
  gross: number;
  netOfVat: number;
  ewt: number;
  pop: EwtProof | null;
}

export const ewtStatus = (r: { pop: EwtProof | null }): "Paid" | "Unpaid" => (r.pop ? "Paid" : "Unpaid");

const round2 = (n: number) => Math.round(n * 100) / 100;

/** The template's column G: gross ÷ 1.12. A sale that charges no VAT has nothing to take out. */
export const netOfVat = (gross: number, chargesVat = true): number => round2(chargesVat ? gross / 1.12 : gross);

/**
 * The supplier row's DATE: the PO date — the same date the 2307 takes its quarter
 * and month from (the owner: *"use the PO date"*). A PO without a usable date
 * falls back to the day the request was raised.
 */
export function supplierEwtDate(src: { poDate: string | null; createdYMD: string }): { date: string; basis: string } {
  if (src.poDate && /^\d{4}-\d{2}-\d{2}/.test(src.poDate)) return { date: src.poDate.slice(0, 10), basis: "PO date" };
  return { date: src.createdYMD, basis: "Request date (PO has no date)" };
}

export interface EwtTotals {
  count: number;
  gross: number;
  netOfVat: number;
  ewt: number;
  paid: number;
  unpaid: number;
  /** EWT still to be remitted (rows without a proof). */
  unpaidEwt: number;
}

export function ewtTotals(rows: readonly EwtRow[]): EwtTotals {
  const sum = (f: (r: EwtRow) => number) => round2(rows.reduce((a, r) => a + f(r), 0));
  const paid = rows.filter((r) => r.pop).length;
  return {
    count: rows.length,
    gross: sum((r) => r.gross),
    netOfVat: sum((r) => r.netOfVat),
    ewt: sum((r) => r.ewt),
    paid,
    unpaid: rows.length - paid,
    unpaidEwt: sum((r) => (r.pop ? 0 : r.ewt)),
  };
}

/** Oldest first, then by name — the order the template lists them in. */
export const sortEwtRows = (rows: EwtRow[]): EwtRow[] =>
  [...rows].sort((a, b) => a.date.localeCompare(b.date) || a.registeredName.localeCompare(b.registeredName) || a.reference.localeCompare(b.reference));

/** A stored proof, or null. */
export function coerceEwtProof(v: unknown): EwtProof | null {
  if (!v || typeof v !== "object") return null;
  const o = v as Record<string, unknown>;
  if (typeof o.path !== "string" || !o.path) return null;
  return {
    path: o.path,
    name: typeof o.name === "string" ? o.name : "proof",
    uploadedAt: typeof o.uploadedAt === "string" ? o.uploadedAt : "",
    byName: typeof o.byName === "string" ? o.byName : "",
  };
}
